using System;
using System.Linq;
using MET.Core;
using UnityEngine;
namespace MET.City {
public sealed partial class CityInterface {
 // One detached world per commit, created only when an archive page needs it.
 V _worldView;
 V W=>_worldView??(_worldView=Runtime.SessionSnapshot);
 string _arcSpecialization="balanced",_arcName="",_arcSponsor="",_arcOpportunity="",_linkFrom="",_linkTo="",_linkResource="food";
 double _linkRate=6,_linkCost=.15;
 string BlockName(V b)=>b.Get("state",V.Map()).Get("block",V.Map()).Get("display_name",b.Get("id","街区")).Text;
 string SpecName(string id)=>V.Map("balanced","综合","agricultural","农业","industrial","工业","services","公共服务","research","科研","logistics","物流").Get(id,id).Text;
 void WorldCommand(Func<CitySession,string> command,Action after=null){var error=Runtime.ExecuteWorld(command);PlayCue(error==""?"confirm":"notice");if(error==""){after?.Invoke();if(_archiveOpen)RenderPage();RefreshContext();}}
 void ArcNavigation(){var nav=Row(_body,"City arc navigation",50);foreach(var item in new[]{new[]{"city","城市与地区"},new[]{"governance","地区治理"},new[]{"network","区域物流"},new[]{"science","科研与工业"},new[]{"city_project","托卡马克之冠"},new[]{"heritage","遗产与城史"},new[]{"content","构筑与成果"}}){var p=item[0];Tab(nav,item[1],p,()=>Navigate(p),_page);}}
 void DistrictStartPage(){Label(_body,"在同一座城市中，开启一段地区任期。",27,Gold);Label(_body,"地区留下土地、居民和产业；街区稳定后可以扩展，交班后地区仍会自治。",18,Muted);var name=InputBox(_body,_arcName,"地区名称（可稍后更改）");name.onValueChanged.AddListener(v=>_arcName=v);SpecializationPicker(_body);var world=W;if(world["blocks"].Count==0)_arcSponsor="";if(world["blocks"].Count>0){Label(_body,"新地区的启动供给来源",19,Gold);if(_arcSponsor==""||!world["blocks"].Has(_arcSponsor))_arcSponsor=world["focused_block_id"].Text;var donors=Row(_body,"District source",48);foreach(var b in world["blocks"].Values){var bid=b["id"].Text;Button(donors,(_arcSponsor==bid?"✓ ":"")+BlockName(b),()=>{_arcSponsor=bid;RenderPage();});}}StartupOpportunityPicker(_body,true);StartupQuote(_body,true);var row=Row(_body,"District landing",350);for(var i=0;i<3;i++){var landing=i;var card=Card(row,new[]{"河湾","林缘旧村","北部高台"}[i],"地点决定真实地形。专业方向与既有城市能力共同影响开局。",i==0?Blue:i==1?Green:Gold);Mark(card,"public",Green,100);Button(card,"建立地区 · 在此登陆",()=>WorldCommand(s=>s.BeginDistrict(landing,_arcSpecialization,_arcName,_arcSponsor,_arcOpportunity)),true);}Fold(_body,"开局来源与规则",p=>Raw(p,W.Get("legacy",V.Map())));}
 void StartupQuote(Transform parent,bool district){var quote=Runtime.Session.StartupView(district,_arcSpecialization,_arcSponsor,_arcOpportunity);var box=Card(parent,"启动投入",quote.Get("reason","").Text,Gold);if(quote.Get("initial_charter",false).Bool){Label(box,"首地区来自城市最初授权，居民与基础建筑沿用当前起源规则。",17,Muted);return;}Metric(box,"通货总投入 / 来源持有",F(quote.Get("quote",V.Map()).Get("money",0).Double)+" / "+F(quote.Get("currency",0).Double));var opportunity=quote.Get("opportunity",V.Map());if(opportunity.Count>0){Label(box,"含规约「"+opportunity.Get("name","").Text+"」的额外投入；以下总额仍从当前来源真实扣除。",17,Gold,65);Label(box,opportunity.Get("tradeoff","").Text,17,Muted,65);LegacyEffects(box,opportunity);LegacyCost(box,opportunity.Get("cost",V.Map()),"规约额外部分");}foreach(var r in quote.Get("quote",V.Map()).Get("stock",V.Map()).Keys)Metric(box,Resource(r),F(quote["quote"]["stock"][r].Double)+" / 来源持有 "+F(quote.Get("available",V.Map()).Get(r,0).Double));}
 void SpecializationPicker(Transform parent){var row=Row(parent,"Specialization",48);foreach(var spec in new[]{"balanced","agricultural","industrial","services","research","logistics"}){var id=spec;Button(row,(_arcSpecialization==id?"✓ ":"")+SpecName(id),()=>{_arcSpecialization=id;_arcOpportunity="";RenderPage();});}}
 void CityArcPage(){ArcNavigation();var world=W;var overview=Card(_body,world.Get("name","来生").Text,"永久 City / 地区任期 / 街区。选择地图只切换视图。",Gold);var summaries=Row(overview,"City identity and clocks",120);var territories=Card(summaries,"城市版图","永久地区与实际街区",Green);Metric(territories,"地区",world["districts"].Count+" 个");Metric(territories,"街区",world["blocks"].Count+" 个");var treasury=Card(summaries,"城市财政","城市层持有的通货",Gold);Metric(treasury,"余额",F(world.Get("treasury",0).Double));var clocks=Card(summaries,"时间记录","现实时间与离开记录",Blue);Metric(clocks,"外部时钟",F(world.Get("external_seconds",0).Double/3600,2)+" 小时");Metric(clocks,"离开时长",F(world.Get("offline_seconds",0).Double/3600,2)+" 小时");
  if(world.Get("active_district_id","").Text=="")Button(overview,"开启下一地区任期",()=>Navigate("district_start"),true);else Button(overview,"扩展当前地区 · 新街区",()=>Navigate("block_start"),true);
  foreach(var district in world["districts"].Values){var did=district["id"].Text;var active=did==world["active_district_id"].Text;var box=Card(_body,district.Get("name",did).Text,active?"正在治理 / 可以调整本地区街区":"自治地区 / 原居民、建筑和供给继续存在",active?Green:Blue);Meter(box,"支持度",district.Get("support",0).Double,100,"",Green);Meter(box,"授权",district.Get("mandate",0).Double,100,"",Gold);foreach(var bidValue in district.Get("block_ids",V.Arr())){var bid=bidValue.Text;var block=world["blocks"].Get(bid,V.Map());var state=block.Get("state",V.Map());var metrics=state.Get("metrics",V.Map());var row=Row(box,"Block navigation",58);Label(row,BlockName(block)+" · "+SpecName(block.Get("specialization","balanced").Text),20);Label(row,F(metrics.Get("population",0).Double,0)+" 人 · "+(block.Get("status","").Text=="stable"?"稳定":"发展中"),16,Muted);Button(row,world["focused_block_id"].Text==bid?"当前地图":"查看实际地图",()=>WorldCommand(s=>s.FocusBlock(bid),CloseArchive));}
   if(!active)Button(box,"查看回任条件",()=>Navigate("governance",did));Fold(box,"地区身份、任期与来源",p=>Raw(p,district));}
 }
 void NewBlockPage(){ArcNavigation();var intro=Card(_body,"新街区的启动供给","选择实际供给来源。启动物资和通货从该街区扣除，并保存来源记录。",Gold);SpecializationPicker(intro);var world=W;if(_arcSponsor==""||!world["blocks"].Has(_arcSponsor))_arcSponsor=world.Get("focused_block_id","").Text;foreach(var block in world["blocks"].Values){var id=block["id"].Text;Button(intro,(_arcSponsor==id?"✓ ":"")+BlockName(block)+" · 供给来源",()=>{_arcSponsor=id;RenderPage();});}StartupOpportunityPicker(_body,false);StartupQuote(_body,false);var row=Row(_body,"New block sites",240);for(var i=0;i<3;i++){var landing=i;var box=Card(row,new[]{"河湾","林缘旧村","北部高台"}[i],"库存、财政或治理资格不足时会说明原因，原地区不会被清空。",Green);Button(box,"支付启动投入 · 登陆",()=>WorldCommand(s=>s.BeginBlock(landing,_arcSpecialization,_arcSponsor,_arcOpportunity)),true);}}
 void GovernancePage(){ArcNavigation();var world=W;var did=_pageContext!=""?_pageContext:world.Get("active_district_id","").Text;if(did==""&&world["focused_block_id"].Text!="")did=world["blocks"][world["focused_block_id"]]["district_id"].Text;var d=world["districts"].Get(did,V.Map());if(d.Count==0){Label(_body,"当前没有治理任期。旧地区继续自治，可以开启新地区。",21);Button(_body,"选择下一地区",()=>Navigate("district_start"),true);return;}var id=did;var intro=Card(_body,d.Get("name",did).Text,"支持度与授权来自真实供给、财政、服务、污染和治理承诺。街区稳定不会结束地区任期。",Gold);Meter(intro,"支持度",d.Get("support",0).Double,100,"",Green);Meter(intro,"授权",d.Get("mandate",0).Double,100,"",Gold);var readings=Runtime.Session.GovernanceView(did);Meter(intro,"实际口粮满足",readings.Get("food",0).Double,1,"",Green);Meter(intro,"实际公共服务覆盖",readings.Get("services",0).Double,1,"",Blue);Metric(intro,"财政月收支",Signed(readings.Get("cashflow",0).Double)+" / 来生月");Meter(intro,"稳定街区承诺",readings.Get("stable_blocks",0).Double,d["promises"].Get("stable_blocks",2).Double," 街区",Gold);var crisis=d.Get("crisis",V.Map());if(crisis.Get("reason","").Text!="")Label(intro,crisis["reason"].Text,18,Red,75);var name=InputBox(intro,d.Get("name","").Text,"为地区命名");Button(intro,"保存地区名称",()=>WorldCommand(s=>s.RenameDistrict(id,name.text)));
  if(did==world["active_district_id"].Text){var focused=world.Get("focused_block_id","").Text;if(focused!=""&&world["blocks"][focused]["district_id"].Text==did)Button(intro,"以实际供给检查当前街区稳定",()=>WorldCommand(s=>s.StabilizeBlock(focused)));Button(intro,"主动交班 · 保留原地区",()=>Confirm("结束本次地区任期？","按实际地区目标检查交班资格。交班后居民、资产与供给继续自治，下一任可以进入新地区。",()=>WorldCommand(s=>s.HandoverDistrict())),true);}else Button(intro,"支付成本 · 回任此地区",()=>Confirm("回任这个地区？","支付实际财政与治理成本。当前任期按规则交接，原街区及库存原样保留。条件不足会说明原因。",()=>WorldCommand(s=>s.ReturnDistrict(id))),true);
  Fold(_body,"实际治理依据、承诺与历次任期",p=>Raw(p,d));}
 void NetworkPage(){ArcNavigation();var view=Runtime.Session.NetworkView();var intro=Card(_body,"区域物流","实际源库存 → 有限在途缓冲 → 目的仓库。节点运力由内部链路和外部交易共同使用，按 External 时间结算。",Blue);var world=W;var blocks=world["blocks"].Values.ToArray();if(blocks.Length>1){if(_linkFrom==""||!world["blocks"].Has(_linkFrom))_linkFrom=blocks[0]["id"].Text;if(_linkTo==""||!world["blocks"].Has(_linkTo))_linkTo=blocks[1]["id"].Text;var from=Row(intro,"Link source",48);Label(from,"来源",18);var to=Row(intro,"Link destination",48);Label(to,"目的",18);foreach(var b in blocks){var id=b["id"].Text;Button(from,(_linkFrom==id?"✓ ":"")+BlockName(b),()=>{_linkFrom=id;RenderPage();});Button(to,(_linkTo==id?"✓ ":"")+BlockName(b),()=>{_linkTo=id;RenderPage();});}var resource=Row(intro,"Resource",48);foreach(var r in new[]{"food","material","goods","advanced_components"}){var key=r;Button(resource,(_linkResource==r?"✓ ":"")+Resource(r),()=>{_linkResource=key;RenderPage();});}var rate=InputBox(intro,F(_linkRate),"每现实小时最大数量");rate.onEndEdit.AddListener(v=>{if(double.TryParse(v,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out var n))_linkRate=n;});var cost=InputBox(intro,F(_linkCost,2),"每单位运输通货成本");cost.onEndEdit.AddListener(v=>{if(double.TryParse(v,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out var n))_linkCost=n;});Button(intro,"建立真实供给链路",()=>WorldCommand(s=>s.CreateLink(_linkFrom,_linkTo,_linkResource,_linkRate,_linkCost)),true);}else Label(intro,"建立第二个街区后可以连接其供给。",18,Muted);
  foreach(var link in world["links"].Values){var id=link["id"].Text;var box=Card(_body,Resource(link["resource"].Text)+" · "+BlockName(world["blocks"][link["from"]])+" → "+BlockName(world["blocks"][link["to"]]),link.Get("last_reason","").Text,Green);Metric(box,"链路上限",F(link.Get("rate",0).Double)+" / 现实小时");Metric(box,"运输成本",F(link.Get("cost",0).Double,2)+" / 单位");Button(box,link.Get("enabled",true).Bool?"暂停运输":"恢复运输",()=>WorldCommand(s=>s.SetLinkEnabled(id,!link.Get("enabled",true).Bool)));Fold(box,"在途、缓冲与实际来源",p=>Raw(p,link));}Fold(_body,"一次世界外部供应与运力结算",p=>Raw(p,view));}
 void SciencePage(){ArcNavigation();var view=Runtime.Session.ScienceView();var intro=Card(_body,"城市科研与高级工业","教育产生的知识是可消耗库存。科研需要投资、持续研究能力和本地时间；高级部件由真实工业投入转化。",Blue);foreach(var row in view.Get("technologies",V.Arr())){var id=row.Get("id","").Text;var box=Card(_body,row.Get("name",id).Text,row.Get("reason",row.Get("status","")).Text,Gold);var current=view.Get("research",V.Map()).Get(id,V.Map());if(current.Count>0){Meter(box,"科研进度",current.Get("progress",0).Double,1,"",Blue);Label(box,current.Get("reason","").Text,16,Muted);}Metric(box,"知识 / 通货 / 材料投入",F(row.Get("knowledge",0).Double)+" / "+F(row.Get("currency",0).Double)+" / "+F(row.Get("material",0).Double));if(id!="")Button(box,row.Get("complete",false).Bool?"技术已完成":"在当前街区投资研究",()=>WorldCommand(s=>s.StartResearch(id,s.FocusedBlockId)),true,row.Get("complete",false).Bool||current.Get("status","").Text=="running");Fold(box,"技术要求与实际投入",p=>Raw(p,row));}if(view.Get("technologies",V.Map()).Count==0){foreach(var idValue in new[]{"precision_engineering","superconductors","fusion_physics"}){var id=idValue;Button(intro,"研究 · "+V.Map("precision_engineering","精密工程","superconductors","超导技术","fusion_physics","聚变物理")[id].Text,()=>WorldCommand(s=>s.StartResearch(id,s.FocusedBlockId)));}}var stockRow=Row(intro,"Knowledge and industry by block",150);var stockCount=0;foreach(var block in W["blocks"].Values){if(stockCount>0&&stockCount%3==0)stockRow=Row(intro,"Knowledge and industry by block",150);stockCount++;var state=block.Get("state",V.Map());var holdings=Card(stockRow,BlockName(block),"当前街区实际库存",Green);Metric(holdings,"可用知识",F(state.Get("knowledge",0).Double,2));double advanced=state.Get("projects",V.Map()).Values.Sum(p=>p.Get("inventory",V.Map()).Get("advanced_components",0).Double);Metric(holdings,"高级部件",F(advanced,2));}Fold(_body,"科研过程与高级工业账本",p=>Raw(p,view));}
 void CityProjectPage(){ArcNavigation();var view=Runtime.Session.ProjectView();var project=view.Get("project",V.Map());var capabilities=view.Get("capabilities",V.Map());var box=Card(_body,"托卡马克之冠","全城工程：来自多个地区的工业、电力、研究能力及真实物资投入。完工后在同一城市继续经营。",CityWorld.BuildingTypeColor("special"));Label(box,project.Get("reason",capabilities.Get("reason","尚未开工")).Text,19,project.Get("status","").Text=="complete"?Gold:Green,65);Button(box,"检查前置并启动工程",()=>WorldCommand(s=>s.StartProject()),true);var bid=Runtime.Session.FocusedBlockId;foreach(var resource in new[]{"material","advanced_components"}){var key=resource;var row=Row(box,"Contribute",48);Label(row,"从当前街区交付 "+Resource(key),18);foreach(var amount in new[]{5.0,15.0,30.0}){var n=amount;Button(row,F(n,0)+" 单位",()=>WorldCommand(s=>s.ContributeProject(bid,key,n)));}}if(project.Has("work"))Meter(box,"累计施工",project["work"].Double,view.Get("requirements",V.Map()).Get("cp",96).Double," CP",Gold);foreach(var resource in new[]{"material","advanced_components"})Meter(box,"实际交付 · "+Resource(resource),project.Get("delivered",V.Map()).Get(resource,0).Double,view["requirements"].Get(resource,0).Double,"",Blue);Fold(_body,"阶段、真实交付、施工来源与前置",p=>Raw(p,view));}
 string HistoryText(V evt){var payload=evt.Get("payload",V.Map());if(evt["kind"].Text=="local_event")return payload.Get("event",V.Map()).Get("text","街区事件").Text;return V.Map("city_founded","城市建立","district_started","开启地区任期","block_started","建立新街区","district_retired","地区交班 / 自治","district_crisis","地区进入治理危机","district_returned","付代价回任","district_named","地区命名","block_stabilized","街区达到稳定条件","institution_founded","地方经验形成永久制度","city_capability","形成城市能力","portable_transferred","许可转移","building_changed","建筑建设 / 升级","building_removed","建筑拆除","population_milestone","居民发展里程碑","local_identity","地方身份变化","research_started","城市研究启动","research_complete","城市技术完成","city_project_started","托卡马克之冠开工","city_project_delivery","城市工程实际交付","city_project_complete","托卡马克之冠建成","reward_claimed","领取成长方案").Get(evt["kind"],"城市记录").Text;}
 void HeritagePage(){ArcNavigation();var world=W;var intro=Card(_body,"地方、可携、制度与城市能力","本地建筑和已部署方案留在原地；可携许可真扣来源副本；地区制度与城市能力保留各自出处。",Gold);var target=world.Get("focused_block_id","").Text;if(target!="")foreach(var source in world["blocks"].Values){var sourceId=source["id"].Text;if(sourceId==target)continue;var wallet=source.Get("state",V.Map()).Get("block",V.Map()).Get("bonus_wallet",V.Map());foreach(var pair in wallet.Pairs){var bonus=pair.Key;if(pair.Value.Get("charges",0).Long<=0)continue;Button(intro,"从 "+BlockName(source)+" 转移1份「"+G.c.bonuses.Get(bonus,V.Map()).Get("name",bonus).Text+"」",()=>WorldCommand(s=>s.TransferPortable(sourceId,bonus,target)));}}Fold(intro,"分层遗产与消费来源",p=>Raw(p,world.Get("legacy",V.Map())));var history=Card(_body,"同一座城市的历史","历史来自实际开局、建设、任期、研究与交付。存载和切换地图不会重播事件。",Blue);foreach(var evt in world.Get("history",V.Arr()).Reverse().Take(140)){Label(history,HistoryText(evt),18);Fold(history,"事件与实体来源",p=>Raw(p,evt));}}
}
}
